    "COMPLETED": "All hypotheses evaluated regarding Tesla's revenue start year.",
    "REMAINING": "-",
    "DECISIONS": "H-5a179e refuted, H-99b0c6 refuted, H-bbbcb8 refuted, H-9a7ea7 supported.",
    "CONTEXT": "No XBRL facts (any concept) exist for Tesla before FY 2011 in the raw EDGAR data, while facts appear from FY 2011 onward."
  },
  "answer": {
    "summary": "Tesla's revenue history appears to start in fiscal year 2011 because the company did not file XBRL‑tagged financials before that year. The absence of any XBRL facts (not just revenue) prior to 2011 indicates a reporting exemption rather than missing or zero revenue values. Consequently, the observed start date reflects a regulatory threshold, not the true beginning of Tesla's operations.",
    "claims": [
      {
        "text": "Tesla has zero XBRL facts (any concept) before fiscal year 2011.",
        "evidence": ["E-4850cc"]
      },
      {
        "text": "Tesla has revenue facts beginning in fiscal year 2011 and continuing through at least 2026.",
        "evidence": ["E-ab997b"]
      }
    ],
    "inferences": [
      {
        "text": "The lack of pre‑2011 XBRL facts is likely because Tesla was a smaller reporting company exempt from mandatory XBRL filing before FY 2011.",
        "basis": "Claim that no XBRL facts exist before 2011 (E-4850cc) combined with known SEC rules for smaller reporting companies."
      },
      {
        "text": "Therefore, the apparent start of Tesla's revenue history in the data reflects a regulatory reporting threshold, not an absence of revenue.",
        "basis": "Same claim as above; if revenue existed but was unreported in XBRL, we would still see XBRL facts for other concepts or zero‑valued revenue facts."
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-5a179e",
        "status": "refuted",
        "evidence": ["E-4850cc"],
        "why": "If only the Revenues concept were inconsistently tagged, other XBRL concepts would still appear; yet no XBRL facts of any concept exist before 2011."
      },
      {
        "id": "H-99b0c6",
        "status": "refuted",
        "evidence": ["E-4850cc"],
        "why": "Zero or minimal revenue would still generate an XBRL fact (value_usd = 0) for the Revenues concept; no such fact exists."
      },
      {
        "id": "H-bbbcb8",
        "status": "refuted",
        "evidence": ["E-4850cc"],
        "why": "The raw EDGAR table contains zero rows for any concept before 2011, so the absence is not due to a hidden filter removing NULL period_frame rows."
      },
      {
        "id": "H-9a7ea7",
        "status": "supported",
        "evidence": ["E-4850cc"],
        "why": "The total absence of any XBRL facts prior to 2011 matches the expectation that Tesla, as a smaller reporting company, was not required to submit XBRL‑tagged financials before the FY 2011 threshold."
      }
    ]
  }
